WHENEVER SQLERROR CONTINUE
ALTER SESSION SET CONTAINER=FREEPDB1;
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.HSM_PASSES CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP TABLE ppiq_src.HSM_COILS CASCADE CONSTRAINTS'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
WHENEVER SQLERROR EXIT SQL.SQLCODE
CREATE TABLE ppiq_src.hsm_coils (coil_id VARCHAR2(40) PRIMARY KEY, slab_id VARCHAR2(40) NOT NULL,
 steel_grade VARCHAR2(20), rolled_utc TIMESTAMP, target_gauge_mm NUMBER(5,2), coil_width_mm NUMBER(6,1),
 coil_weight_t NUMBER(7,2), coil_length_m NUMBER(8,1), finish_temp_c NUMBER(6,1), coiling_temp_c NUMBER(6,1),
 roll_campaign_id NUMBER(5), lube_viscosity_cst NUMBER(5,1), campaign_wear_idx NUMBER(6,1));
CREATE TABLE ppiq_src.hsm_passes (pass_id VARCHAR2(40) PRIMARY KEY, coil_id VARCHAR2(40) NOT NULL,
 slab_id VARCHAR2(40) NOT NULL, stand_no NUMBER(2), pass_utc TIMESTAMP, entry_temp_c NUMBER(6,1), exit_temp_c NUMBER(6,1),
 reduction_pct NUMBER(5,3), rolling_force_kn NUMBER(8,1), strip_width_mm NUMBER(6,1), strip_thick_mm NUMBER(6,2),
 lube_viscosity_cst NUMBER(5,1), roll_campaign_id NUMBER(5));
COMMIT;
SELECT COUNT(*) AS coils FROM ppiq_src.hsm_coils;
EXIT;
